static const unsigned int BYTE_PER_PIXEL = 3;

sinoscope_t* sinoscope_create(char* name, sinoscope_handler handler, unsigned int width, unsigned int height,
                              float max) {
    sinoscope_t* sinoscope = malloc(sizeof(*sinoscope));
    if (sinoscope == NULL) {
        LOG_ERROR_ERRNO("malloc");
        goto fail_exit;
    }

    sinoscope->name    = name;
    sinoscope->handler = handler;

    sinoscope->buffer_size = width * height * BYTE_PER_PIXEL;
    sinoscope->buffer      = malloc(sinoscope->buffer_size);
    if (sinoscope->buffer == NULL) {
        LOG_ERROR_ERRNO("malloc");
        goto fail_free_sinoscope;
    }

    sinoscope->width  = width;
    sinoscope->height = height;
    sinoscope->taylor = 3;

    sinoscope->interval         = color_get_interval(max);
    sinoscope->interval_inverse = color_get_interval_inverse(max);

    sinoscope->time   = 0;
    sinoscope->max    = max;
    sinoscope->phase0 = 0;
    sinoscope->phase1 = 0;
    sinoscope->dx     = 3 * M_PI / width;
    sinoscope->dy     = 3 * M_PI / height;
    sinoscope->opencl = NULL;

    return sinoscope;

fail_free_sinoscope:
    free(sinoscope);
fail_exit:
    return NULL;
}

void sinoscope_destroy(sinoscope_t* sinoscope) {
    free(sinoscope->buffer);
    free(sinoscope);
}

int sinoscope_corners(sinoscope_t* sinoscope) {
    if (sinoscope == NULL) {
        LOG_ERROR_NULL_PTR();
        goto fail_exit;
    }

    if (sinoscope->width == 0) {
        LOG_ERROR("invalid width received");
        goto fail_exit;
    }

    if (sinoscope->height == 0) {
        LOG_ERROR("invalid height received");
        goto fail_exit;
    }

    float time = sinoscope->time;
    float fact = (sinoscope->width * sinoscope->height) * 0.5;
    float max  = 1000000.0;

    sinoscope->phase0 = ((max / 2) * sinf(time * 0.1) + (max / 2)) / fact;
    sinoscope->phase1 = ((max / 2) * sinf(time * 0.2) + (max / 2)) / fact;
    sinoscope->time += 0.01;

    if (sinoscope->time > 2 * M_PI * 1000) {
        sinoscope->time -= 2 * M_PI * 1000;
    }

    return 0;

fail_exit:
    return -1;
}

static int compare_methods(sinoscope_t* serial, sinoscope_t* openmp, sinoscope_t* opencl) {
    int status;
    sinoscope_t* base;
    sinoscope_t* compare;
    long long max_diff;

    base = serial;

    if (openmp) {
        max_diff = 0;
        compare  = openmp;
    } else {
        compare  = opencl;
        max_diff = 10;
    }

    if (base->buffer_size != compare->buffer_size) {
        LOG_ERROR("buffer sizes mismatch");
        goto fail_exit;
    }

    unsigned int buffer_size = base->buffer_size;

    status = sinoscope_corners(base);
    status += sinoscope_corners(compare);

    if (status != 0) {
        LOG_ERROR("failed to forward sinoscope");
        goto fail_exit;
    }

    status = base->handler(serial);
    status += compare->handler(compare);

    if (status != 0) {
        LOG_ERROR("failed to call sinoscope handler");
        goto fail_exit;
    }

    for (int i = 0; i < buffer_size; i++) {
        int base_value    = base->buffer[i];
        int compare_value = compare->buffer[i];

        if (abs(compare_value - base_value) > max_diff) {
            printf("[%d] differs from [%d] at %d\n", compare_value, base_value, i);
            exit(EXIT_FAILURE);
        }
    }

    return 0;

fail_exit:
    return -1;
}

int sinoscope_check(unsigned int width, unsigned int height, unsigned int taylor, float max,
                    sinoscope_opencl_t* opencl) {
    sinoscope_t* sinoscope_serial = NULL;
    sinoscope_t* sinoscope_openmp = NULL;
    sinoscope_t* sinoscope_opencl = NULL;

    sinoscope_serial = sinoscope_create("serial", sinoscope_image_serial, width, height, max);
    if (sinoscope_serial == NULL) {
        LOG_ERROR("failed to create sinoscope (serial)");
        goto fail_exit;
    }
    sinoscope_serial->taylor = taylor;

    if (!opencl) {
        sinoscope_openmp = sinoscope_create("openmp", sinoscope_image_openmp, width, height, max);
        if (sinoscope_openmp == NULL) {
            LOG_ERROR("failed to create sinoscope (openmp)");
            goto fail_exit;
        }
        sinoscope_openmp->taylor = taylor;
    } else {
        sinoscope_opencl = sinoscope_create("opencl", sinoscope_image_opencl, width, height, max);
        if (sinoscope_opencl == NULL) {
            LOG_ERROR("failed to create sinoscope (opencl)");
            goto fail_exit;
        }
        sinoscope_opencl->taylor = taylor;
        sinoscope_opencl->opencl = opencl;
    }

    for (int i = 0; i < 10; i++) {
        float time             = (((float)rand()) / ((float)RAND_MAX)) * (2 * M_PI * 1000);
        sinoscope_serial->time = time;
        if (!opencl) {
            sinoscope_openmp->time = time;
        } else {
            sinoscope_opencl->time = time;
        }

        if (compare_methods(sinoscope_serial, sinoscope_openmp, sinoscope_opencl) < 0) {
            LOG_ERROR("error when comparing results");
            goto fail_exit;
        }
    }

    sinoscope_destroy(sinoscope_serial);

    if (!opencl) {
        sinoscope_destroy(sinoscope_openmp);
    } else {
        sinoscope_destroy(sinoscope_opencl);
    }

    return 0;

fail_exit:
    if (sinoscope_serial != NULL) {
        sinoscope_destroy(sinoscope_serial);
    }

    if (sinoscope_openmp != NULL) {
        sinoscope_destroy(sinoscope_openmp);
    }

    if (sinoscope_opencl != NULL) {
        sinoscope_destroy(sinoscope_opencl);
    }

    return -1;
}

typedef struct benchmark_result {
    uint64_t user_us;
    uint64_t system_us;
    uint64_t elapsed_us;
} benchmark_result_t;

static int benchmark_measure(sinoscope_t* sinoscope, unsigned int iterations, benchmark_result_t* result) {
    uint64_t start_user, start_system;
    uint64_t end_user, end_system;

    if (platform_cpu_times_us(&start_user, &start_system) < 0) {
        LOG_ERROR("failed to get the CPU times");
        goto fail_exit;
    }

    uint64_t start_time = platform_now_us();

    for (unsigned int i = 0; i < iterations; i++) {
        if (sinoscope_corners(sinoscope) < 0) {
            LOG_ERROR("failed to forward sinoscope");
            goto fail_exit;
        }

        if (sinoscope->handler(sinoscope) < 0) {
            LOG_ERROR("failed to call sinoscope handler `%s`", sinoscope->name);
            goto fail_exit;
        }
    }

    uint64_t end_time = platform_now_us();

    if (platform_cpu_times_us(&end_user, &end_system) < 0) {
        LOG_ERROR("failed to get the CPU times");
        goto fail_exit;
    }

    result->user_us    = end_user - start_user;
    result->system_us  = end_system - start_system;
    result->elapsed_us = end_time - start_time;

    return 0;

fail_exit:
    return -1;
}

static void benchmark_print_header(bool with_speedup) {
    printf("test    width   height  iterations   user (us)  system (us)  elapsed (us)%s\n",
           with_speedup ? "  speedup" : "");
}

static void benchmark_print_row(const sinoscope_t* sinoscope, unsigned int iterations, const benchmark_result_t* result,
                                const benchmark_result_t* baseline) {
    printf("%s\t%5u    %5u    %8u  %10" PRIu64 "   %10" PRIu64 "    %10" PRIu64, sinoscope->name, sinoscope->width,
           sinoscope->height, iterations, result->user_us, result->system_us, result->elapsed_us);

    if (baseline != NULL) {
        printf("  %6.2fx", result->elapsed_us > 0 ? (double)baseline->elapsed_us / (double)result->elapsed_us : 0.0);
    }

    printf("\n");
}

int sinoscope_benchmark(sinoscope_t* sinoscope, unsigned int iterations) {
    benchmark_result_t result;

    if (benchmark_measure(sinoscope, iterations, &result) < 0) {
        return -1;
    }

    benchmark_print_header(false);
    benchmark_print_row(sinoscope, iterations, &result, NULL);

    return 0;
}

int sinoscope_benchmarks(unsigned int width, unsigned int height, unsigned int taylor, float max,
                         sinoscope_opencl_t* opencl, unsigned int iterations) {
    sinoscope_t* sinoscope_serial = NULL;
    sinoscope_t* sinoscope_openmp = NULL;
    sinoscope_t* sinoscope_opencl = NULL;

    sinoscope_serial = sinoscope_create("serial", sinoscope_image_serial, width, height, max);
    if (sinoscope_serial == NULL) {
        LOG_ERROR("failed to create sinoscope (serial)");
        goto fail_exit;
    }
    sinoscope_serial->taylor = taylor;

    sinoscope_openmp = sinoscope_create("openmp", sinoscope_image_openmp, width, height, max);
    if (sinoscope_openmp == NULL) {
        LOG_ERROR("failed to create sinoscope (openmp)");
        goto fail_exit;
    }
    sinoscope_openmp->taylor = taylor;

    sinoscope_opencl = sinoscope_create("opencl", sinoscope_image_opencl, width, height, max);
    if (sinoscope_opencl == NULL) {
        LOG_ERROR("failed to create sinoscope (opencl)");
        goto fail_exit;
    }
    sinoscope_opencl->taylor = taylor;
    sinoscope_opencl->opencl = opencl;

    benchmark_result_t serial_result, openmp_result, opencl_result;

    if (benchmark_measure(sinoscope_serial, iterations, &serial_result) < 0) {
        LOG_ERROR("failed to benchmark (serial)");
        goto fail_exit;
    }

    if (benchmark_measure(sinoscope_openmp, iterations, &openmp_result) < 0) {
        LOG_ERROR("failed to benchmark (openmp)");
        goto fail_exit;
    }

    if (benchmark_measure(sinoscope_opencl, iterations, &opencl_result) < 0) {
        LOG_ERROR("failed to benchmark (opencl)");
        goto fail_exit;
    }

    printf("================================================================================\n");
    printf("============================== benchmark results ===============================\n");
    printf("================================================================================\n");
    benchmark_print_header(true);
    benchmark_print_row(sinoscope_serial, iterations, &serial_result, &serial_result);
    benchmark_print_row(sinoscope_openmp, iterations, &openmp_result, &serial_result);
    benchmark_print_row(sinoscope_opencl, iterations, &opencl_result, &serial_result);
    printf("================================================================================\n");

    sinoscope_destroy(sinoscope_serial);
    sinoscope_destroy(sinoscope_openmp);
    sinoscope_destroy(sinoscope_opencl);

    return 0;

fail_exit:
    if (sinoscope_serial != NULL) {
        sinoscope_destroy(sinoscope_serial);
    }

    if (sinoscope_openmp != NULL) {
        sinoscope_destroy(sinoscope_openmp);
    }

    if (sinoscope_opencl != NULL) {
        sinoscope_destroy(sinoscope_opencl);
    }

    return -1;
}

int sinoscope_save_image(sinoscope_t* sinoscope, char* filename) {
    if (sinoscope_corners(sinoscope) < 0) {
        LOG_ERROR("failed to forward sinoscope");
        goto fail_exit;
    }

    if (sinoscope->handler(sinoscope) < 0) {
        LOG_ERROR("failed to call sinoscope handler `%s`", sinoscope->name);
        goto fail_exit;
    }

    image_t* image = image_create(sinoscope->width, sinoscope->height);
    if (image == NULL) {
        LOG_ERROR("failed to create image");
        goto fail_exit;
    }

    for (int j = 0; j < sinoscope->height; j++) {
        for (int i = 0; i < sinoscope->width; i++) {
            pixel_t* pixel = image_get_pixel(image, i, j);
            if (pixel == NULL) {
                LOG_ERROR("failed to get pixel");
                goto fail_free_image;
            }

            unsigned int index = (i * 3) + (j * 3) * sinoscope->width;
            pixel->bytes[0]    = sinoscope->buffer[index + 0];
            pixel->bytes[1]    = sinoscope->buffer[index + 1];
            pixel->bytes[2]    = sinoscope->buffer[index + 2];
        }
    }

    if (image_save_png(image, filename) < 0) {
        LOG_ERROR("failed to save image");
        goto fail_free_image;
    }

    image_destroy(image);

    return 0;

fail_free_image:
    image_destroy(image);
fail_exit:
    return -1;
}
